import Foundation

// MARK: - Clipboard Filter
//
// Pure policy for what may enter the clipboard history. Kept free of
// Cocoa/NSPasteboard so it can be unit-tested headlessly.
//
// Privacy rules (in order):
//   1. Drop concealed/transient/auto-generated pasteboards (password
//      managers like 1Password and system auto-paste mark these).
//   2. Drop empty or whitespace-only text.
//   3. Drop oversized blobs (history is a convenience, not an archive).

enum ClipboardFilter {

    static let blockedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
    ]

    static let maxTextLength = 100_000

    static func shouldStore(types: [String], text: String) -> Bool {
        if types.contains(where: { blockedTypes.contains($0) }) { return false }
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return false }
        if text.count > maxTextLength { return false }
        return true
    }
}
